    final values = _values[language];
    if (values == null) return null;
    final normalized = english.replaceAll('…', '...').toLowerCase();
    for (final entry in values.entries) {
      if (entry.key.replaceAll('…', '...').toLowerCase() == normalized) return entry.value;
    }
    return null;
